const MAPA_MOVIMIENTO = {
  'Alquiler cobrado': 'Alquiler',
  'Suministros cobrados': 'Suministros',
  'Fianza recibida': 'Fianza / Depósito',
  'Fianza devuelta': 'Fianza / Depósito',
  'Rotación tradicional propietario': 'Rotacion_Tradicional',
  'Rotación habitación propietario': 'Rotacion_Propietario',
  'Rotación habitación inquilino': 'Rotacion_Habitacion_Inquilino',
  'Reparación y conservación': 'Gasto_Reparacion',
};

const IGNORAR = ['Honorarios de gestión', 'Transferencia a propietario', 'Coste colaborador interno'];

const MAPA_ESTADO = {
  'Cobrado': 'validado',
  'Compensado': 'validado',
  'Pagado': 'validado',
  'Pendiente': 'pendiente_validar',
  'Cobrado parcialmente': 'pago_parcial',
};

function serieExcelAFecha(serie) {
  if (typeof serie !== 'number') return null;
  const utc_days = Math.floor(serie - 25569);
  const utc_value = utc_days * 86400;
  return new Date(utc_value * 1000).toISOString().split('T')[0];
}

const items = $input.all();
const result = [];

for (const item of items) {
  const r = item.json.row;
  if (!r) continue;

  // Índices según cabecera real: 0=Fecha,1=Piso,2=Movimiento,3=Concepto,4=Base,5=Margen,6=ImporteBanco,7=Estado,8=Factura,9=Observaciones
  const fecha = r[0];
  const piso = r[1];
  const movimiento = r[2];
  const concepto = r[3];
  const base = r[4];
  const importeBanco = r[6];
  const estadoOriginal = r[7];

  if (!movimiento || !fecha || IGNORAR.includes(movimiento) || estadoOriginal === 'Anulado') {
    continue;
  }

  const pisoTexto = String(piso || '');
  const codigoMatch = pisoTexto.match(/^([A-Z0-9_-]+)\s*[–-]/);
  const codigoRentila = codigoMatch ? codigoMatch[1].trim() : null;
  if (!codigoRentila) continue;

  const tipo = MAPA_MOVIMIENTO[movimiento] || 'Otro_Requiere_Revision';
  const estado = MAPA_ESTADO[estadoOriginal] || 'pendiente_validar';
  const monto = base || importeBanco || 0;
  const fechaFormateada = serieExcelAFecha(fecha) || fecha;

  result.push({
    json: {
      codigo_rentila: codigoRentila,
      fecha: fechaFormateada,
      de_a: String(concepto || ''),
      monto: parseFloat(monto) || 0,
      tipo: tipo,
      descripcion: String(concepto || ''),
      estado_validacion: estado,
      referencia_original: `${fechaFormateada}_${codigoRentila}_${movimiento}_${monto}`
    }
  });
}

return result;

const items = $('Parsear Registro').all();

return [{
  json: {
    movimientos_procesados: items.length,
    total_importado: Math.round(items.reduce((sum, i) => sum + parseFloat(i.json.monto || 0), 0) * 100) / 100
  }
}];
